// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "staticlib/RealityETH-3.0.sol";

contract KaiSign is ReentrancyGuard, AccessControl, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    uint32 public constant DEFAULT_TIMEOUT = 172800; // 48 hours in seconds
    uint256 public constant INCENTIVE_CLAWBACK_PERIOD = 604800; // 7 days in seconds
    uint256 public constant COMMIT_REVEAL_TIMEOUT = 2592000; // 30 days in seconds
    uint256 public constant INCENTIVE_DURATION = 2592000; // 30 days in seconds
    uint256 public constant PLATFORM_FEE_PERCENT = 5; // 5%
    string public constant VERSION = "1.0.0";

    address public immutable realityETH;
    address public immutable arbitrator;
    address public immutable treasury;
    uint256 public minBond;
    uint256 public templateId;

    enum Status { Created, Proposed, Settled }

    struct Spec {
        uint64 createdTimestamp;
        uint64 proposedTimestamp;
        Status status;
        uint80 totalBonds;
        uint32 reserved;
        address creator;
        address targetContract;
        bytes32 blobHash;
        bytes32 questionId;
        bytes32 incentiveId;
        uint256 chainId;
    }

    struct Commitment {
        address committer;
        uint64 commitTimestamp;
        uint32 reserved1;
        address targetContract;
        bool isRevealed;
        uint80 bondAmount;
        uint8 reserved;
        uint64 revealDeadline;
        uint256 chainId;
        bytes32 incentiveId;
    }

    struct Incentive {
        address creator;
        uint80 amount;
        uint16 reserved1;
        uint64 deadline;
        uint64 createdAt;
        address targetContract;
        bool isClaimed;
        bool isActive;
        uint256 chainId;
        string description;
    }

    mapping(bytes32 => Spec) public specs;
    mapping(bytes32 => bytes32) public specBlobHash;
    mapping(bytes32 => Commitment) public commitments;
    mapping(bytes32 => Incentive) public incentives;
    mapping(bytes32 => address) public specOwners;
    mapping(uint256 => mapping(address => bytes32[])) public contractSpecs;
    mapping(uint256 => mapping(address => uint256)) public contractSpecCount;
    mapping(uint256 => mapping(address => uint256)) public incentivePool;
    mapping(uint256 => mapping(address => uint256)) public poolContributorCount;
    mapping(address => bytes32[]) public userIncentives;
    mapping(bytes32 => mapping(address => uint256)) public userBonds;
    mapping(bytes32 => mapping(address => uint256)) public poolContributions;
    mapping(bytes32 => mapping(address => uint256)) public userContributions;

    error InvalidContract();
    error ContractNotFound();
    error AlreadyProposed();
    error NotProposed();
    error AlreadySettled();
    error NotFinalized();
    error InsufficientBond();
    error InsufficientIncentive();
    error IncentiveExpired();
    error NoIncentiveToClaim();
    error CommitmentNotFound();
    error CommitmentAlreadyRevealed();
    error CommitmentExpired();
    error InvalidReveal();
    error ClawbackTooEarly();
    error Unauthorized();

    event LogCreateSpec(address indexed creator, bytes32 indexed specID, bytes32 indexed blobHash, address targetContract, uint256 chainId, uint256 timestamp, bytes32 incentiveId);
    event LogContractSpecAdded(address indexed targetContract, bytes32 indexed specID, address indexed creator, uint256 chainId, bytes32 blobHash);
    event LogProposeSpec(address indexed user, bytes32 indexed specID, bytes32 questionId, uint256 bond);
    event LogHandleResult(bytes32 indexed specID, bool isAccepted);
    event LogIncentiveCreated(bytes32 indexed incentiveId, address indexed creator, address indexed targetContract, uint256 chainId, uint256 amount, uint64 deadline, string description);
    event LogIncentiveClaimed(bytes32 indexed incentiveId, address indexed claimer, bytes32 indexed specID, uint256 amount);
    event LogIncentiveClawback(bytes32 indexed incentiveId, address indexed creator, uint256 amount);
    event LogCommitSpec(address indexed committer, bytes32 indexed commitmentId, address indexed targetContract, uint256 chainId, uint256 bondAmount, uint64 revealDeadline);
    event LogRevealSpec(address indexed creator, bytes32 indexed specID, bytes32 indexed blobHash, bytes32 commitmentId, address targetContract, uint256 chainId);
    event LogEmergencyPause(address indexed admin);
    event LogEmergencyUnpause(address indexed admin);

    constructor(
        address _realityETH,
        address _arbitrator,
        address _treasury,
        uint256 _minBond,
        address[] memory _initialAdmins
    ) {
        require(_realityETH != address(0), "Invalid RealityETH address");
        require(_arbitrator != address(0), "Invalid arbitrator address");
        require(_treasury != address(0), "Invalid treasury address");
        require(_initialAdmins.length > 0, "No initial admins");

        realityETH = _realityETH;
        arbitrator = _arbitrator;
        treasury = _treasury;
        minBond = _minBond;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        for (uint256 i = 0; i < _initialAdmins.length; i++) {
            _grantRole(ADMIN_ROLE, _initialAdmins[i]);
        }

        templateId = RealityETH_v3_0(realityETH).createTemplate(
            '{"title": "Is the ERC7730 specification %s for contract %s on chain %s correct?", "type": "bool", "category": "misc"}'
        );
    }

    function createIncentive(
        address targetContract,
        uint256 targetChainId,
        uint256 amount,
        uint64 duration,
        string calldata description
    ) external payable nonReentrant whenNotPaused returns (bytes32 incentiveId) {
        require(targetContract != address(0), "Invalid contract address");
        require(amount > 0, "Amount must be greater than zero");
        require(amount <= type(uint80).max, "Amount exceeds maximum");
        require(duration > 0 && duration <= INCENTIVE_DURATION, "Invalid duration");
        require(msg.value >= amount, "Insufficient ETH sent");
        require(msg.value == amount, "Exact amount required");

        incentiveId = keccak256(abi.encodePacked(msg.sender, targetContract, amount, targetChainId, block.timestamp, description));
        uint64 expiry = uint64(block.timestamp + duration);

        Incentive memory incentive = Incentive({
            creator: msg.sender,
            amount: uint80(amount),
            reserved1: 0,
            deadline: expiry,
            createdAt: uint64(block.timestamp),
            targetContract: targetContract,
            isClaimed: false,
            isActive: true,
            chainId: targetChainId,
            description: description
        });

        incentives[incentiveId] = incentive;
        userIncentives[msg.sender].push(incentiveId);
        incentivePool[targetChainId][targetContract] += amount;
        poolContributions[incentiveId][msg.sender] += amount;
        poolContributorCount[targetChainId][targetContract] += 1;

        if (msg.value > amount) {
            (bool success,) = msg.sender.call{value: msg.value - amount}("");
            require(success, "Excess ETH refund failed");
        }

        emit LogIncentiveCreated(incentiveId, msg.sender, targetContract, targetChainId, amount, expiry, description);
        return incentiveId;
    }

    function commitSpec(
        bytes32 commitment,
        address targetContract,
        uint256 targetChainId
    ) external nonReentrant whenNotPaused {
        require(targetContract != address(0), "Invalid contract address");
        require(targetChainId > 0, "Invalid chain ID");
        require(minBond > 0, "Minimum bond not set");
        require(msg.value >= minBond, "Insufficient bond amount");
        require(msg.value <= type(uint80).max, "Bond exceeds maximum");

        bytes32 commitmentId = keccak256(abi.encodePacked(commitment, msg.sender, targetContract, targetChainId, block.timestamp));
        uint64 revealDeadline = uint64(block.timestamp + COMMIT_REVEAL_TIMEOUT);

        Commitment memory newCommitment = Commitment({
            committer: msg.sender,
            commitTimestamp: uint64(block.timestamp),
            reserved1: 0,
            targetContract: targetContract,
            isRevealed: false,
            bondAmount: uint80(msg.value),
            reserved: 0,
            revealDeadline: revealDeadline,
            chainId: targetChainId,
            incentiveId: 0
        });

        commitments[commitmentId] = newCommitment;
        emit LogCommitSpec(msg.sender, commitmentId, targetContract, targetChainId, msg.value, revealDeadline);
    }

    function revealSpec(
        bytes32 commitmentId,
        bytes32 blobHash,
        bytes32 metadataHash,
        uint256 nonce
    ) external payable nonReentrant whenNotPaused returns (bytes32 specID) {
        Commitment storage commitment = commitments[commitmentId];
        require(commitment.committer == msg.sender, "Unauthorized");
        require(!commitment.isRevealed, "Already revealed");
        require(block.timestamp <= commitment.revealDeadline, "Reveal deadline passed");
        require(msg.value > 0, "No incentive provided");
        require(minBond > 0, "Minimum bond not set");
        require(msg.value <= type(uint80).max, "Incentive exceeds maximum");

        bytes32 computedCommitment = keccak256(abi.encodePacked(blobHash, metadataHash, nonce));
        require(
            keccak256(abi.encodePacked(computedCommitment, msg.sender, commitment.targetContract, commitment.chainId, commitment.commitTimestamp))
            == commitmentId,
            "Invalid reveal"
        );

        specID = keccak256(abi.encodePacked(msg.sender, blobHash, commitment.targetContract, commitment.chainId, block.timestamp));
        require(specs[specID].creator == address(0), "Spec already exists");

        commitment.isRevealed = true;

        Spec memory newSpec = Spec({
            createdTimestamp: uint64(block.timestamp),
            proposedTimestamp: 0,
            status: Status.Created,
            totalBonds: uint80(commitment.bondAmount),
            reserved: 0,
            creator: msg.sender,
            targetContract: commitment.targetContract,
            blobHash: blobHash,
            questionId: 0,
            incentiveId: 0,
            chainId: commitment.chainId
        });

        specs[specID] = newSpec;
        specBlobHash[specID] = blobHash;
        contractSpecs[commitment.chainId][commitment.targetContract].push(specID);
        contractSpecCount[commitment.chainId][commitment.targetContract] += 1;
        userBonds[specID][msg.sender] = commitment.bondAmount;

        emit LogCreateSpec(msg.sender, specID, blobHash, commitment.targetContract, commitment.chainId, block.timestamp, 0);
        emit LogRevealSpec(msg.sender, specID, blobHash, commitmentId, commitment.targetContract, commitment.chainId);

        return specID;
    }

    function proposeSpec(bytes32 specID) external payable nonReentrant whenNotPaused {
        Spec storage spec = specs[specID];
        require(spec.creator != address(0), "Spec not found");
        require(spec.status == Status.Created, "Already proposed");
        require(msg.value >= minBond, "Insufficient bond");
        require(msg.value <= type(uint80).max, "Bond exceeds maximum");

        spec.totalBonds += uint80(msg.value);
        spec.status = Status.Proposed;
        spec.proposedTimestamp = uint64(block.timestamp);

        userBonds[specID][msg.sender] += msg.value;

        string memory question = string(abi.encodePacked(
            "Is the ERC7730 specification ",
            _bytes32ToString(spec.blobHash),
            " for contract ",
            _addressToString(spec.targetContract),
            " on chain ",
            _uint256ToString(spec.chainId),
            " correct?"
        ));

        bytes32 questionId = RealityETH_v3_0(realityETH).askQuestionWithMinBond(
            templateId,
            question,
            arbitrator,
            DEFAULT_TIMEOUT,
            0,
            0,
            minBond
        );

        spec.questionId = questionId;
        emit LogProposeSpec(msg.sender, specID, questionId, msg.value);
    }

    function handleResult(bytes32 specID) external nonReentrant whenNotPaused {
        Spec storage spec = specs[specID];
        require(spec.status == Status.Proposed, "Not proposed");

        bool isFinalized = RealityETH_v3_0(realityETH).isFinalized(spec.questionId);
        require(isFinalized, "Question not finalized");

        bytes32 result = RealityETH_v3_0(realityETH).resultFor(spec.questionId);
        bool isAccepted = (result != 0);

        spec.status = Status.Settled;
        emit LogHandleResult(specID, isAccepted);

        if (isAccepted) {
            // Pay platform fee
            if (spec.incentiveId != 0) {
                Incentive storage incentive = incentives[spec.incentiveId];
                uint256 platformFee = (incentive.amount * PLATFORM_FEE_PERCENT) / 100;
                uint256 claimerAmount = incentive.amount - platformFee;

                (bool treasurySuccess,) = treasury.call{value: platformFee}("");
                require(treasurySuccess, "Treasury transfer failed");

                (bool claimerSuccess,) = spec.creator.call{value: claimerAmount}("");
                require(claimerSuccess, "Claimer transfer failed");

                emit LogIncentiveClaimed(spec.incentiveId, spec.creator, specID, claimerAmount);
            }
        }
    }

    function clawbackIncentive(bytes32 incentiveId) external nonReentrant whenNotPaused {
        Incentive storage incentive = incentives[incentiveId];
        require(incentive.creator != address(0), "Incentive not found");
        require(incentive.creator == msg.sender, "Unauthorized");
        require(block.timestamp >= incentive.deadline + INCENTIVE_CLAWBACK_PERIOD, "Clawback too early");
        require(incentive.isActive, "Incentive not active");

        incentive.isActive = false;
        uint256 amount = incentive.amount;

        (bool success,) = msg.sender.call{value: amount}("");
        require(success, "Clawback transfer failed");

        emit LogIncentiveClawback(incentiveId, msg.sender, amount);
    }

    // View functions
    function getSpecBlobHash(bytes32 specID) external view returns (bytes32) {
        return specBlobHash[specID];
    }

    function getContractSpecCount(address targetContract, uint256 chainId) external view returns (uint256) {
        return contractSpecCount[chainId][targetContract];
    }

    function getIncentivePool(address targetContract, uint256 chainId) external view returns (uint256 poolAmount, uint256 contributorCount) {
        return (incentivePool[chainId][targetContract], poolContributorCount[chainId][targetContract]);
    }

    function getSpecsByContract(address targetContract, uint256 chainId) external view returns (bytes32[] memory) {
        return contractSpecs[chainId][targetContract];
    }

    function getSpecsByContractPaginated(
        address targetContract,
        uint256 chainId,
        uint256 offset,
        uint256 limit
    ) external view returns (bytes32[] memory specIds, uint256 total) {
        bytes32[] storage allSpecs = contractSpecs[chainId][targetContract];
        total = allSpecs.length;

        if (offset >= total) {
            return (new bytes32[](0), total);
        }

        uint256 end = offset + limit;
        if (end > total) {
            end = total;
        }

        specIds = new bytes32[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            specIds[i - offset] = allSpecs[i];
        }
    }

    function getUserIncentives(address user) external view returns (bytes32[] memory) {
        return userIncentives[user];
    }

    // Admin functions
    function addAdmin(address newAdmin) external onlyRole(ADMIN_ROLE) {
        _grantRole(ADMIN_ROLE, newAdmin);
    }

    function removeAdmin(address admin) external onlyRole(ADMIN_ROLE) {
        _revokeRole(ADMIN_ROLE, admin);
    }

    function setMinBond(uint256 _minBond) external onlyRole(ADMIN_ROLE) {
        minBond = _minBond;
    }

    function emergencyPause() external onlyRole(ADMIN_ROLE) {
        _pause();
        emit LogEmergencyPause(msg.sender);
    }

    function emergencyUnpause() external onlyRole(ADMIN_ROLE) {
        require(paused(), "Not paused");
        _unpause();
        emit LogEmergencyUnpause(msg.sender);
    }

    // Internal helper functions
    function _bytes32ToString(bytes32 _bytes32) internal pure returns (string memory) {
        uint8 i = 0;
        while (i < 32 && _bytes32[i] != 0) {
            i++;
        }
        bytes memory bytesArray = new bytes(i);
        for (i = 0; i < 32 && _bytes32[i] != 0; i++) {
            bytesArray[i] = _bytes32[i];
        }
        return string(bytesArray);
    }

    function _addressToString(address _address) internal pure returns (string memory) {
        bytes32 _bytes = bytes32(uint256(uint160(_address)));
        bytes memory HEX = "0123456789abcdef";
        bytes memory _string = new bytes(42);
        _string[0] = "0";
        _string[1] = "x";
        for (uint i = 0; i < 20; i++) {
            _string[2 + i * 2] = HEX[uint8(_bytes[i + 12] >> 4)];
            _string[3 + i * 2] = HEX[uint8(_bytes[i + 12] & 0x0f)];
        }
        return string(_string);
    }

    function _uint256ToString(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) {
            return "0";
        }
        uint j = _i;
        uint len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint k = len;
        while (_i != 0) {
            k = k - 1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }
}
